INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch06$PT142-S1-Q19$batch06$, 142, 1, 19, $batch06$Parallel$batch06$, $batch06$If temperatures had dropped below freezing when I was gone last week, the impatiens in my garden would have died. If the impatiens had died, they obviously could not continue to bloom. However, since the impatiens in my garden are still in bloom today, temperatures did not drop below freezing last week.$batch06$, $batch06$The pattern of reasoning in which one of the following arguments most closely parallels that in the argument above?$batch06$, $batch06$A$batch06$, true, $batch06$Batch 06; question text from local bank.$batch06$ FROM lr_sections s WHERE s.preptest=142 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT142-S1-Q19$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$A$batch06$, $batch06$If a species is highly adaptable, it will thrive when introduced into a new environment. If a species thrives in its new environment, it will have an adverse effect on species already existing in that environment. But, since this species has not had an adverse effect on any species already existing in its new environment, it is not highly adaptable.$batch06$, $batch06$Correct$batch06$, true FROM lr_questions q WHERE q.qid=$batch06$PT142-S1-Q19$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$A$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$B$batch06$, $batch06$If a species thrives in a new environment, that species is adaptable. Species that adapt to new environments adversely affect some species already existing in those environments. So, if a species does not adversely affect any species already existing in its new environment, it has not adapted to it.$batch06$, $batch06$Bad Conclusion Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT142-S1-Q19$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$B$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$C$batch06$, $batch06$If a species is introduced into a new environment, it adversely affects some species already existing in that environment, but only if it adapts well to it. Therefore, if a species does not adapt well to a new environment, it will not adversely affect any species already existing in it.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT142-S1-Q19$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$C$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$D$batch06$, $batch06$If the introduction of a new species would adversely affect some species already existing in an environment, that species should not be introduced into it. Therefore, since the introduction of species into new environments will result in some species in those environments being adversely affected, species should probably not be introduced into new environments.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT142-S1-Q19$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$D$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$E$batch06$, $batch06$If a new species would damage an environment, that species should not be introduced into it. If a new species is introduced, the risk can be reduced by controlling its population. Therefore, because the introduction of species into new environments is likely to happen, their populations should be controlled.$batch06$, $batch06$Bad Premise Match$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT142-S1-Q19$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$E$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT142-S1-Q19$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$Temperatures did not drop below freezing last week.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Freezing would have killed the impatiens. Dead impatiens could not still bloom. The impatiens are still blooming.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Strip it to a chain. If A then B. If B then C. Not C. So not A. (Freezing, dead, not blooming; they are blooming, so no freezing.) Look for a two-link chain, a denied final result, and a conclusion that denies the first link.$batch06$), (3, $batch06$Goal$batch06$, $batch06$If A then B, if B then C; not C, so not A.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT142-S1-Q19$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$If adaptable, it thrives. If it thrives, it harms existing species. It has harmed none, so it is not adaptable. A perfect chain match.$batch06$), ($batch06$B$batch06$, $batch06$The conclusion is a conditional ("if it does not affect ..., it has not adapted"), not a flat denial. The original concludes "not A" outright.$batch06$), ($batch06$C$batch06$, $batch06$One rule with "only if", and a conditional conclusion. No chain, no denied result.$batch06$), ($batch06$D$batch06$, $batch06$This is about what *should* be done, and it never denies a result to work backward.$batch06$), ($batch06$E$batch06$, $batch06$A recommendation built on what is likely to happen. Nothing like the original's chain.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT142-S1-Q19$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
